customCSS:
.t, .history { color: #5c6370; }
.join { color: #98c379; }
.part, .quit { color: #5c6370; }
.kick, .error { color: #e06c75; }
.notice { color: #e5c07b; }
.action { color: #c678dd; }
.mode, .nick, .topic, .server { color: #56b6c2; }
.highlight { color: #dcdfe4; background-color: #474e5d; border-left: 3px solid #c678dd; padding-left: 8px; }
.reply { color: #5c6370; border-left: 2px solid #61afef; padding-left: 6px; }
.oper { color: #282c34; background-color: #e5c07b; }
.reactions { color: #61afef; background-color: #21252b; }
.card { background-color: #21252b; border-color: #5c6370; }
.card-title { color: #61afef; }
.card-desc { color: #5c6370; }
.daychange { color: #5c6370; border-color: #21252b; }
